import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.stream.Stream;

public class ExtensionFileFilterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String find(Path dir, String extension) {
        try {
            java.util.List<String> names = ExtensionFileFilter.namesWithExtension(dir, extension);
            return names == null ? "null" : names.toString();
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) throws Exception {
        Path dir = Files.createTempDirectory("extfilter");
        try {
            for (String name : new String[] {"notes.TXT", "a.txt", "b.log", "txt", "zebra.txt", "report.Log"}) {
                Files.write(dir.resolve(name), "x".getBytes(StandardCharsets.US_ASCII));
            }
            Path sub = Files.createDirectory(dir.resolve("archive.txt"));
            Files.write(sub.resolve("hidden.txt"), "y".getBytes(StandardCharsets.US_ASCII));

            check("txt files sorted", "[a.txt, notes.TXT, zebra.txt]", find(dir, "txt"));
            check("extension argument is case insensitive too", "[a.txt, notes.TXT, zebra.txt]", find(dir, "TXT"));
            check("log files", "[b.log, report.Log]", find(dir, "log"));
            check("no matches", "[]", find(dir, "md"));
            check("directory named archive.txt is excluded", false, find(dir, "txt").contains("archive"));
            check("does not recurse", false, find(dir, "txt").contains("hidden"));
            check("a file called txt does not match", false, find(dir, "txt").contains(" txt,"));
        } finally {
            try (Stream<Path> paths = Files.walk(dir)) {
                for (Path p : paths.sorted(Comparator.reverseOrder()).toList()) {
                    Files.deleteIfExists(p);
                }
            }
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

