import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.stream.Stream;

public class ExtensionFileFilter {

    public static List<String> namesWithExtension(Path dir, String extension) throws IOException {
        String suffix = ("." + extension).toLowerCase(Locale.US);
        List<String> names = new ArrayList<>();
        try (Stream<Path> entries = Files.list(dir)) {
            for (Path entry : entries.toList()) {
                String name = entry.getFileName().toString();
                if (Files.isRegularFile(entry) && name.toLowerCase(Locale.US).endsWith(suffix)) {
                    names.add(name);
                }
            }
        }
        Collections.sort(names);
        return names;
    }
}
